pragma solidity 0.8.25;

import "openzeppelin-contracts/contracts/token/ERC721/IERC721.sol";
import "../interfaces/IAccountManager.sol";
import "../interfaces/IBonusManager.sol";
import "../interfaces/ILockManager.sol";
import "../interfaces/IMigrationManager.sol";
import "../interfaces/INFTAttributesManager.sol";
import "./BaseBlastManager.sol";
import "../interfaces/ISnuggeryManager.sol";
import "../interfaces/IMunchadexManager.sol";

// All bonuses denominated in 1e18 (1e18 is a 100% bonus so 30e16 is a 30% bonus)
contract BonusManager is IBonusManager, BaseBlastManager {
    ILockManager _lockManager;
    IMigrationManager _migrationManager;
    INFTAttributesManager _nftAttributesManager;
    IAccountManager _accountManager;
    IMunchadexManager _munchadexManager;

    uint256 public referralBonus;
    int16[] public realmBonuses;
    uint8[] public rarityBonuses;
    uint8[] public munchablesPerRealm;
    uint8[] public munchablesPerRarity;
    uint8[] public raritySetBonuses;
    uint8 public totalMunchables;
    uint256 minETHPetBonus;
    uint256 maxETHPetBonus;
    uint256 petBonusDivisor;
    uint256 migrationBonus;
    uint256 migrationBonusEndTime;

    constructor(address _configStorage) {
        __BaseConfigStorage_setConfigStorage(_configStorage);
        _reconfigure();
    }

    function _reconfigure() internal {
        _migrationManager = IMigrationManager(
            configStorage.getAddress(StorageKey.MigrationManager)
        );
        _lockManager = ILockManager(
            configStorage.getAddress(StorageKey.LockManager)
        );
        _nftAttributesManager = INFTAttributesManager(
            configStorage.getAddress(StorageKey.NFTAttributesManager)
        );
        _accountManager = IAccountManager(
            configStorage.getAddress(StorageKey.AccountManager)
        );
        _munchadexManager = IMunchadexManager(
            configStorage.getAddress(StorageKey.MunchadexManager)
        );
        referralBonus = configStorage.getUint(StorageKey.ReferralBonus);

        realmBonuses = configStorage.getSmallIntArray(StorageKey.RealmBonuses);
        rarityBonuses = configStorage.getSmallUintArray(
            StorageKey.RarityBonuses
        );
        totalMunchables = uint8(
            configStorage.getUint(StorageKey.TotalMunchables)
        );
        munchablesPerRealm = configStorage.getSmallUintArray(
            StorageKey.MunchablesPerRealm
        );
        munchablesPerRarity = configStorage.getSmallUintArray(
            StorageKey.MunchablesPerRarity
        );
        raritySetBonuses = configStorage.getSmallUintArray(
            StorageKey.RaritySetBonuses
        );

        minETHPetBonus = configStorage.getUint(StorageKey.MinETHPetBonus);
        maxETHPetBonus = configStorage.getUint(StorageKey.MaxETHPetBonus);
        petBonusDivisor = configStorage.getUint(StorageKey.PetBonusMultiplier);

        migrationBonus = configStorage.getUint(StorageKey.MigrationBonus);
        migrationBonusEndTime = configStorage.getUint(
            StorageKey.MigrationBonusEndTime
        );

        super.__BaseBlastManager_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    function getFeedBonus(
        address _caller,
        uint256 _tokenId
    ) external view override returns (int256) {
        // Calculate bonuses for snuggery realm and rarity
        MunchablesCommonLib.NFTImmutableAttributes
            memory immutableAttributes = _nftAttributesManager
                .getImmutableAttributes(_tokenId);
        (, MunchablesCommonLib.Player memory player) = _accountManager
            .getPlayer(_caller);

        if (uint256(immutableAttributes.rarity) >= rarityBonuses.length)
            revert InvalidRarityError(uint256(immutableAttributes.rarity));

        uint8 rarityBonus = uint8(
            rarityBonuses[uint256(immutableAttributes.rarity)]
        );

        uint256 realmIndex = (uint256(immutableAttributes.realm) * 5) +
            uint256(player.snuggeryRealm);
        if (realmIndex >= realmBonuses.length)
            revert InvalidRealmBonus(realmIndex);

        int8 realmBonus = int8(realmBonuses[realmIndex]);

        int16 sumBonuses = int16(realmBonus) + int16(int8(rarityBonus));
        int256 finalBonus = int256(1e16) * int256(sumBonuses);

        finalBonus = finalBonus < -20e16 ? int256(-20e16) : finalBonus;
        finalBonus = finalBonus > 100e16 ? int256(100e16) : finalBonus;

        return finalBonus;
    }

    function getHarvestBonus(
        address _caller
    ) external view override returns (uint256) {
        uint256 weightedValue = _lockManager.getLockedWeightedValue(_caller);
        ILockManager.PlayerSettings memory _settings = _lockManager
            .getPlayerSettings(_caller);
        uint256 _migrationBonus;
        if (block.timestamp < migrationBonusEndTime) {
            _migrationBonus = _calculateMigrationBonus(_caller, weightedValue);
        }
        return
            _calculateLockBonus(_settings.lockDuration) +
            _migrationBonus +
            _calculateLevelBonus(_caller) +
            _calculateMunchadexBonus(_caller);
    }

    function getPetBonus(
        address _petter
    ) external view override returns (uint256) {
        ILockManager.PlayerSettings memory _settings = _lockManager
            .getPlayerSettings(_petter);
        return _calculateLockBonus(_settings.lockDuration);
    }

    function _calculateLockBonus(
        uint32 lockDuration
    ) internal pure returns (uint256 _lockBonusPercent) {
        uint256 _daysStaked = lockDuration / 1 days;
        if (_daysStaked >= 30) {
            uint256 bonus4Pct = (1e16 * 4 * (_daysStaked - 30)) / 15;
            uint256 bonus14Pct = (1e16 * 14 * (_daysStaked - 30)) / 60;
            _lockBonusPercent = bonus4Pct + bonus14Pct;
        }
    }

    // TODO: Do we want to expose these for front-end?
    function _calculateMigrationBonus(
        address _caller,
        uint256 weightedValue
    ) internal view returns (uint256 _migrationBonus) {
        (
            bool didMigrate,
            IMigrationManager.MigrationTotals memory totals
        ) = _migrationManager.getUserMigrationCompletedData(_caller);
        ILockManager.ConfiguredToken memory configuredToken = _lockManager
            .getConfiguredToken(totals.tokenLocked);
        if (didMigrate) {
            // Change to double original amount
            uint256 usdPrice = configuredToken.usdPrice;
            uint256 migrateHighestAmount = (2 *
                totals.totalLockedAmount *
                usdPrice) / 1e18;
            uint256 halfAmount = ((totals.totalLockedAmount * usdPrice) /
                1e18) / 2;
            if (weightedValue >= migrateHighestAmount) {
                // Full bonus
                _migrationBonus = migrationBonus;
            } else if (weightedValue >= halfAmount) {
                // Calculate bonus from delta
                _migrationBonus =
                    (migrationBonus * (weightedValue - halfAmount)) /
                    (migrateHighestAmount - halfAmount);
            }
        }
    }

    function _calculateLevelBonus(
        address _caller
    ) internal view returns (uint256 _levelBonus) {
        (
            ,
            MunchablesCommonLib.Player memory player,
            MunchablesCommonLib.SnuggeryNFT[] memory _snuggery
        ) = _accountManager.getFullPlayerData(_caller);
        uint256 _snuggerySize = _snuggery.length;

        if (_snuggerySize > 0) {
            uint i;
            for (; i < _snuggerySize; i++) {
                _levelBonus += _nftAttributesManager
                    .getAttributes(_snuggery[i].tokenId)
                    .level;
            }
            _levelBonus *= 1e16;
            _levelBonus /= (_snuggerySize * 200);
            _levelBonus += _snuggerySize == player.maxSnuggerySize ? 3e16 : 0;
        }
    }

    function _calculateMunchadexBonus(
        address _caller
    ) internal view returns (uint256 _munchadexBonus) {
        (
            uint256[] memory numMunchablesPerRealm,
            uint256[] memory numMunchablesPerRarity,
            uint256 numUnique
        ) = _munchadexManager.getMunchadexInfo(_caller);

        if (numUnique == 125) {
            _munchadexBonus += 100;
        } else {
            uint8 i;
            bool perRealmUnique = true;
            bool perRealmGreaterThan6 = true;
            for (
                ;
                i < numMunchablesPerRealm.length &&
                    i < munchablesPerRealm.length;
                i++
            ) {
                if (numMunchablesPerRealm[i] < 6) {
                    perRealmGreaterThan6 = false;
                    if (numMunchablesPerRealm[i] == 0) {
                        perRealmUnique = false;
                    }
                } else if (numMunchablesPerRealm[i] == munchablesPerRealm[i]) {
                    _munchadexBonus += 3;
                }
            }
            if (perRealmUnique && perRealmGreaterThan6) {
                _munchadexBonus += 2;
            } else if (perRealmUnique) {
                _munchadexBonus += 1;
            }
            i = 0;
            for (
                ;
                i < numMunchablesPerRarity.length &&
                    i < munchablesPerRarity.length;
                i++
            ) {
                if (numMunchablesPerRarity[i] == munchablesPerRarity[i])
                    _munchadexBonus += raritySetBonuses[i];
            }
        }
        _munchadexBonus *= 1e16;
    }

    function getReferralBonus() external view override returns (uint256) {
        return referralBonus * 1e16;
    }
}
"},"src/managers/ClaimManager.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import "../interfaces/IClaimManager.sol";
import "../interfaces/IMunchToken.sol";
import "../interfaces/IAccountManager.sol";
import "../interfaces/IConfigStorage.sol";
import "../interfaces/IBonusManager.sol";
import "./BaseBlastManagerUpgradeable.sol";
import "../interfaces/ISnuggeryManager.sol";

contract ClaimManager is IClaimManager, BaseBlastManagerUpgradeable {
    uint256[] POINTS_PER_MIGRATED_NFT;
    uint256 POINTS_PER_UNREVEALED_NFT;

    Period public currentPeriod;
    uint256 public pointsPerPeriod;
    IAccountManager accountManager;
    ISnuggeryManager snuggeryManager;
    IBonusManager bonusManager;
    IMunchToken munchToken;

    bool _swapEnabled;
    uint256 _pointsPerToken;

    mapping(address => uint32) _lastClaimPeriod;
    mapping(uint32 => uint256) _pointsExcess;
    mapping(address => uint256) _points;

    modifier onlyValidPeriod() {
        if (
            (currentPeriod.id != 0 &&
                uint32(block.timestamp) > currentPeriod.endTime) ||
            uint32(block.timestamp) < currentPeriod.startTime
        )
            revert InvalidPeriodError(
                uint32(block.timestamp),
                currentPeriod.startTime,
                currentPeriod.endTime
            );
        _;
    }

    modifier onlySwappable() {
        if (!_swapEnabled) revert SwapDisabledError();
        _;
    }

    constructor() {
        _disableInitializers();
    }

    function initialize(address _configStorage) public override initializer {
        BaseBlastManagerUpgradeable.initialize(_configStorage);
        _reconfigure();
    }

    function _reconfigure() internal {
        accountManager = IAccountManager(
            configStorage.getAddress(StorageKey.AccountManager)
        );
        bonusManager = IBonusManager(
            configStorage.getAddress(StorageKey.BonusManager)
        );
        snuggeryManager = ISnuggeryManager(
            configStorage.getAddress(StorageKey.SnuggeryManager)
        );
        munchToken = IMunchToken(
            configStorage.getAddress(StorageKey.MunchToken)
        );

        pointsPerPeriod = configStorage.getUint(StorageKey.PointsPerPeriod);
        _pointsPerToken = configStorage.getUint(StorageKey.PointsPerToken);
        _swapEnabled = configStorage.getBool(StorageKey.SwapEnabled);

        POINTS_PER_MIGRATED_NFT = configStorage.getUintArray(
            StorageKey.PointsPerMigratedNFT
        );
        POINTS_PER_UNREVEALED_NFT = configStorage.getUint(
            StorageKey.PointsPerUnrevealedNFT
        );

        super.__BaseBlastManagerUpgradeable_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    function newPeriod() external override notPaused onlyRole(Role.NewPeriod) {
        if (
            currentPeriod.endTime != 0 &&
            uint32(block.timestamp) < currentPeriod.endTime
        ) revert CurrentPeriodNotEndedError();

        uint256 prevPeriodClaimed = currentPeriod.claimed;

        currentPeriod.id++;
        uint32 _currentPeriodId = currentPeriod.id;
        uint256 _excess;
        if (currentPeriod.claimed <= currentPeriod.available) {
            _excess = currentPeriod.available - currentPeriod.claimed;
        }
        _pointsExcess[_currentPeriodId] = _excess;
        currentPeriod.startTime = uint32(block.timestamp);
        currentPeriod.endTime = uint32(block.timestamp + 1 days);
        currentPeriod.available = pointsPerPeriod;
        currentPeriod.claimed = 0;
        currentPeriod.globalTotalChonk = snuggeryManager.getGlobalTotalChonk();

        emit NewPeriodStarted(
            _currentPeriodId,
            currentPeriod.startTime,
            currentPeriod.endTime,
            currentPeriod.available,
            prevPeriodClaimed,
            _excess,
            currentPeriod.globalTotalChonk
        );
    }

    function burnNFTsForPoints(
        address _player,
        uint8[] memory _tokenIdsByRarity
    )
        external
        override
        onlyConfiguredContract(StorageKey.MigrationManager)
        returns (uint256 _receivedPoints)
    {
        uint256 totalPoints;
        for (uint8 i; i < _tokenIdsByRarity.length; i++) {
            totalPoints += (_tokenIdsByRarity[i] * POINTS_PER_MIGRATED_NFT[i]);
        }
        _points[_player] += totalPoints;
        _receivedPoints = totalPoints;
        emit NFTsBurnedForPoints(_player, _tokenIdsByRarity, totalPoints);
    }

    function burnUnrevealedForPoints(
        address _player,
        uint256 _unrevealed
    )
        external
        override
        onlyConfiguredContract(StorageKey.MigrationManager)
        returns (uint256 _receivedPoints)
    {
        uint256 totalPoints = POINTS_PER_UNREVEALED_NFT * _unrevealed;
        _points[_player] += totalPoints;
        _receivedPoints = totalPoints;
        emit UnrevealedSwappedForPoints(_player, _unrevealed, totalPoints);
    }

    function claimPoints() external override onlyValidPeriod {
        address mainAccount = accountManager.getMainAccount(msg.sender);

        _claimPoints(mainAccount);
    }

    /// @inheritdoc IClaimManager
    function forceClaimPoints(
        address _player
    )
        external
        onlyValidPeriod
        onlyConfiguredContract(StorageKey.SnuggeryManager)
    {
        _claimPoints(_player);
    }

    function spendPoints(
        address _player,
        uint256 _spendPoints
    ) external override onlyConfiguredContract(StorageKey.SnuggeryManager) {
        if (_points[_player] < _spendPoints) revert NotEnoughPointsError();
        _points[_player] -= _spendPoints;

        emit PointsSpent(_player, _spendPoints);
    }

    function convertPointsToTokens(
        uint256 _pointsToConvert
    ) external notPaused onlySwappable {
        uint256 _pointsAvailable = _points[msg.sender];
        if (_pointsToConvert == 0 || _pointsAvailable == 0)
            revert NoClaimablePointsError();
        if (_pointsAvailable < _pointsToConvert) revert NotEnoughPointsError();
        if (_pointsPerToken == 0) revert PointsPerTokenNotSetError();

        uint256 _tokensToMint = (_pointsToConvert * _pointsPerToken) / 1e12;
        if (_tokensToMint == 0) revert PointAmountToSmallError();

        _points[msg.sender] -= _pointsToConvert;

        munchToken.mint(msg.sender, _tokensToMint);

        emit PointsConverted(msg.sender, _pointsToConvert, _tokensToMint);
    }

    function getCurrentPeriod() external view override returns (Period memory) {
        return currentPeriod;
    }

    function getPoints(
        address _player
    ) external view override returns (uint256) {
        return _points[accountManager.getMainAccount(_player)];
    }

    function _claimPoints(address _player) private {
        (, MunchablesCommonLib.Player memory player) = accountManager.getPlayer(
            _player
        );

        uint32 currentPeriodId = currentPeriod.id;
        if (_lastClaimPeriod[_player] < currentPeriodId) {
            // ignore if previously claimed because check is done for player facing function

            uint256 availablePoints = currentPeriod.available +
                _pointsExcess[currentPeriodId];
            uint256 claimAmount;
            if (currentPeriod.globalTotalChonk > 0) {
                claimAmount =
                    (snuggeryManager.getTotalChonk(_player) * availablePoints) /
                    currentPeriod.globalTotalChonk;
            }

            if (claimAmount > 0) {
                // TODO: Think about ways to keep this within total emission instead of
                // adding to the total count
                uint256 _referralBonus;
                if (player.referrer != address(0)) {
                    _referralBonus =
                        (claimAmount * bonusManager.getReferralBonus()) /
                        1e18;
                    _points[player.referrer] += _referralBonus;
                }
                _lastClaimPeriod[_player] = currentPeriodId;
                _points[_player] += claimAmount;
                currentPeriod.claimed += claimAmount;

                emit Claimed(
                    msg.sender,
                    _player,
                    currentPeriodId,
                    claimAmount,
                    player.referrer,
                    _referralBonus
                );
            }
        }
        _lastClaimPeriod[_player] = currentPeriodId;
        emit ClaimPeriodHit(
            _player,
            _lastClaimPeriod[_player],
            currentPeriod.id
        );
    }
}
"},"src/managers/LandManager.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import "../interfaces/ILandManager.sol";
import "../interfaces/ILockManager.sol";
import "../interfaces/IAccountManager.sol";
import "./BaseBlastManagerUpgradeable.sol";
import "../interfaces/INFTAttributesManager.sol";
import "openzeppelin-contracts/contracts/token/ERC721/IERC721.sol";

contract LandManager is BaseBlastManagerUpgradeable, ILandManager {
    uint256 MIN_TAX_RATE;
    uint256 MAX_TAX_RATE;
    uint256 DEFAULT_TAX_RATE;
    uint256 BASE_SCHNIBBLE_RATE;
    uint256 PRICE_PER_PLOT;
    int16[] REALM_BONUSES;
    uint8[] RARITY_BONUSES;

    // landlord to plot metadata
    mapping(address => PlotMetadata) plotMetadata;
    // landlord to plot id to plot
    mapping(address => mapping(uint256 => Plot)) plotOccupied;
    // token id to original owner
    mapping(uint256 => address) munchableOwner;
    // main account to staked munchables list
    mapping(address => uint256[]) munchablesStaked;
    // token id -> toiler state
    mapping(uint256 => ToilerState) toilerState;

    ILockManager lockManager;
    IAccountManager accountManager;
    IERC721 munchNFT;
    INFTAttributesManager nftAttributesManager;

    constructor() {
        _disableInitializers();
    }

    modifier forceFarmPlots(address _account) {
        _farmPlots(_account);
        _;
    }

    function initialize(address _configStorage) public override initializer {
        BaseBlastManagerUpgradeable.initialize(_configStorage);
        _reconfigure();
    }

    function _reconfigure() internal {
        // load config from the config storage contract and configure myself
        lockManager = ILockManager(
            IConfigStorage(configStorage).getAddress(StorageKey.LockManager)
        );
        accountManager = IAccountManager(
            IConfigStorage(configStorage).getAddress(StorageKey.AccountManager)
        );
        munchNFT = IERC721(configStorage.getAddress(StorageKey.MunchNFT));
        nftAttributesManager = INFTAttributesManager(
            IConfigStorage(configStorage).getAddress(
                StorageKey.NFTAttributesManager
            )
        );

        MIN_TAX_RATE = IConfigStorage(configStorage).getUint(
            StorageKey.LockManager
        );
        MAX_TAX_RATE = IConfigStorage(configStorage).getUint(
            StorageKey.AccountManager
        );
        DEFAULT_TAX_RATE = IConfigStorage(configStorage).getUint(
            StorageKey.ClaimManager
        );
        BASE_SCHNIBBLE_RATE = IConfigStorage(configStorage).getUint(
            StorageKey.MigrationManager
        );
        PRICE_PER_PLOT = IConfigStorage(configStorage).getUint(
            StorageKey.NFTOverlord
        );
        REALM_BONUSES = configStorage.getSmallIntArray(StorageKey.RealmBonuses);
        RARITY_BONUSES = configStorage.getSmallUintArray(
            StorageKey.RarityBonuses
        );

        __BaseBlastManagerUpgradeable_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    function updateTaxRate(uint256 newTaxRate) external override notPaused {
        (address landlord, ) = _getMainAccountRequireRegistered(msg.sender);
        if (newTaxRate < MIN_TAX_RATE || newTaxRate > MAX_TAX_RATE)
            revert InvalidTaxRateError();
        if (plotMetadata[landlord].lastUpdated == 0)
            revert PlotMetadataNotUpdatedError();
        uint256 oldTaxRate = plotMetadata[landlord].currentTaxRate;
        plotMetadata[landlord].currentTaxRate = newTaxRate;
        emit TaxRateChanged(landlord, oldTaxRate, newTaxRate);
    }

    // Only to be triggered by msg sender if they had locked before the land manager was deployed
    function triggerPlotMetadata() external override notPaused {
        (address mainAccount, ) = _getMainAccountRequireRegistered(msg.sender);
        if (plotMetadata[mainAccount].lastUpdated != 0)
            revert PlotMetadataTriggeredError();
        plotMetadata[mainAccount] = PlotMetadata({
            lastUpdated: block.timestamp,
            currentTaxRate: DEFAULT_TAX_RATE
        });

        emit UpdatePlotsMeta(mainAccount);
    }

    function updatePlotMetadata(
        address landlord
    ) external override onlyConfiguredContract(StorageKey.AccountManager) {
        if (plotMetadata[landlord].lastUpdated == 0) {
            plotMetadata[landlord] = PlotMetadata({
                lastUpdated: block.timestamp,
                currentTaxRate: DEFAULT_TAX_RATE
            });
        } else {
            plotMetadata[landlord].lastUpdated = block.timestamp;
        }

        emit UpdatePlotsMeta(landlord);
    }

    function stakeMunchable(
        address landlord,
        uint256 tokenId,
        uint256 plotId
    ) external override forceFarmPlots(msg.sender) notPaused {
        (address mainAccount, ) = _getMainAccountRequireRegistered(msg.sender);
        if (landlord == mainAccount) revert CantStakeToSelfError();
        if (plotOccupied[landlord][plotId].occupied)
            revert OccupiedPlotError(landlord, plotId);
        if (munchablesStaked[mainAccount].length > 10)
            revert TooManyStakedMunchiesError();
        if (munchNFT.ownerOf(tokenId) != mainAccount)
            revert InvalidOwnerError();

        uint256 totalPlotsAvail = _getNumPlots(landlord);
        if (plotId >= totalPlotsAvail) revert PlotTooHighError();

        if (
            !munchNFT.isApprovedForAll(mainAccount, address(this)) &&
            munchNFT.getApproved(tokenId) != address(this)
        ) revert NotApprovedError();
        munchNFT.transferFrom(mainAccount, address(this), tokenId);

        plotOccupied[landlord][plotId] = Plot({
            occupied: true,
            tokenId: tokenId
        });

        munchablesStaked[mainAccount].push(tokenId);
        munchableOwner[tokenId] = mainAccount;

        toilerState[tokenId] = ToilerState({
            lastToilDate: block.timestamp,
            plotId: plotId,
            landlord: landlord,
            latestTaxRate: plotMetadata[landlord].currentTaxRate,
            dirty: false
        });

        emit FarmPlotTaken(toilerState[tokenId], tokenId);
    }

    function unstakeMunchable(
        uint256 tokenId
    ) external override forceFarmPlots(msg.sender) notPaused {
        (address mainAccount, ) = _getMainAccountRequireRegistered(msg.sender);
        ToilerState memory _toiler = toilerState[tokenId];
        if (_toiler.landlord == address(0)) revert NotStakedError();
        if (munchableOwner[tokenId] != mainAccount) revert InvalidOwnerError();

        plotOccupied[_toiler.landlord][_toiler.plotId] = Plot({
            occupied: false,
            tokenId: 0
        });
        toilerState[tokenId] = ToilerState({
            lastToilDate: 0,
            plotId: 0,
            landlord: address(0),
            latestTaxRate: 0,
            dirty: false
        });
        munchableOwner[tokenId] = address(0);
        _removeTokenIdFromStakedList(mainAccount, tokenId);

        munchNFT.transferFrom(address(this), mainAccount, tokenId);
        emit FarmPlotLeave(_toiler.landlord, tokenId, _toiler.plotId);
    }

    function transferToUnoccupiedPlot(
        uint256 tokenId,
        uint256 plotId
    ) external override forceFarmPlots(msg.sender) notPaused {
        (address mainAccount, ) = _getMainAccountRequireRegistered(msg.sender);
        ToilerState memory _toiler = toilerState[tokenId];
        uint256 oldPlotId = _toiler.plotId;
        uint256 totalPlotsAvail = _getNumPlots(_toiler.landlord);
        if (_toiler.landlord == address(0)) revert NotStakedError();
        if (munchableOwner[tokenId] != mainAccount) revert InvalidOwnerError();
        if (plotOccupied[_toiler.landlord][plotId].occupied)
            revert OccupiedPlotError(_toiler.landlord, plotId);
        if (plotId >= totalPlotsAvail) revert PlotTooHighError();

        toilerState[tokenId].latestTaxRate = plotMetadata[_toiler.landlord]
            .currentTaxRate;
        plotOccupied[_toiler.landlord][oldPlotId] = Plot({
            occupied: false,
            tokenId: 0
        });
        plotOccupied[_toiler.landlord][plotId] = Plot({
            occupied: true,
            tokenId: tokenId
        });

        emit FarmPlotLeave(_toiler.landlord, tokenId, oldPlotId);
        emit FarmPlotTaken(toilerState[tokenId], tokenId);
    }

    function farmPlots() external override notPaused {
        _farmPlots(msg.sender);
    }

    function _farmPlots(address _sender) internal {
        (
            address mainAccount,
            MunchablesCommonLib.Player memory renterMetadata
        ) = _getMainAccountRequireRegistered(_sender);

        uint256[] memory staked = munchablesStaked[mainAccount];
        MunchablesCommonLib.NFTImmutableAttributes memory immutableAttributes;
        ToilerState memory _toiler;
        uint256 timestamp;
        address landlord;
        uint256 tokenId;
        int256 finalBonus;
        uint256 schnibblesTotal;
        uint256 schnibblesLandlord;
        for (uint8 i = 0; i < staked.length; i++) {
            timestamp = block.timestamp;
            tokenId = staked[i];
            _toiler = toilerState[tokenId];
            if (_toiler.dirty) continue;
            landlord = _toiler.landlord;
            // use last updated plot metadata time if the plot id doesn't fit
            // track a dirty bool to signify this was done once
            // the edge case where this doesnt work is if the user hasnt farmed in a while and the landlord
            // updates their plots multiple times. then the last updated time will be the last time they updated their plot details
            // instead of the first
            if (_getNumPlots(landlord) < _toiler.plotId) {
                timestamp = plotMetadata[landlord].lastUpdated;
                toilerState[tokenId].dirty = true;
            }
            (
                ,
                MunchablesCommonLib.Player memory landlordMetadata
            ) = _getMainAccountRequireRegistered(landlord);

            immutableAttributes = nftAttributesManager.getImmutableAttributes(
                tokenId
            );
            finalBonus =
                int16(
                    REALM_BONUSES[
                        (uint256(immutableAttributes.realm) * 5) +
                            uint256(landlordMetadata.snuggeryRealm)
                    ]
                ) +
                int16(
                    int8(RARITY_BONUSES[uint256(immutableAttributes.rarity)])
                );
            schnibblesTotal =
                (timestamp - _toiler.lastToilDate) *
                BASE_SCHNIBBLE_RATE;
            schnibblesTotal = uint256(
                (int256(schnibblesTotal) +
                    (int256(schnibblesTotal) * finalBonus)) / 100
            );
            schnibblesLandlord =
                (schnibblesTotal * _toiler.latestTaxRate) /
                1e18;

            toilerState[tokenId].lastToilDate = timestamp;
            toilerState[tokenId].latestTaxRate = plotMetadata[_toiler.landlord]
                .currentTaxRate;

            renterMetadata.unfedSchnibbles += (schnibblesTotal -
                schnibblesLandlord);

            landlordMetadata.unfedSchnibbles += schnibblesLandlord;
            landlordMetadata.lastPetMunchable = uint32(timestamp);
            accountManager.updatePlayer(landlord, landlordMetadata);
            emit FarmedSchnibbles(
                _toiler.landlord,
                tokenId,
                _toiler.plotId,
                schnibblesTotal - schnibblesLandlord,
                schnibblesLandlord
            );
        }
        accountManager.updatePlayer(mainAccount, renterMetadata);
    }

    function _removeTokenIdFromStakedList(
        address mainAccount,
        uint256 tokenId
    ) internal {
        uint256 stakedLength = munchablesStaked[mainAccount].length;
        bool found = false;
        for (uint256 i = 0; i < stakedLength; i++) {
            if (munchablesStaked[mainAccount][i] == tokenId) {
                munchablesStaked[mainAccount][i] = munchablesStaked[
                    mainAccount
                ][stakedLength - 1];
                found = true;
                munchablesStaked[mainAccount].pop();
                break;
            }
        }

        if (!found) revert InvalidTokenIdError();
    }

    function _getMainAccountRequireRegistered(
        address _account
    ) internal view returns (address, MunchablesCommonLib.Player memory) {
        (
            address _mainAccount,
            MunchablesCommonLib.Player memory _player
        ) = accountManager.getPlayer(_account);

        if (_player.registrationDate == 0) revert PlayerNotRegisteredError();
        return (_mainAccount, _player);
    }

    function _getNumPlots(address _account) internal view returns (uint256) {
        return lockManager.getLockedWeightedValue(_account) / PRICE_PER_PLOT;
    }
}
"},"src/managers/LockManager.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../interfaces/ILockManager.sol";
import "../interfaces/IConfigStorage.sol";
import "../interfaces/IAccountManager.sol";
import "../interfaces/IMigrationManager.sol";
import "./BaseBlastManager.sol";
import "../interfaces/ISnuggeryManager.sol";
import "../interfaces/INFTOverlord.sol";

contract LockManager is BaseBlastManager, ILockManager, ReentrancyGuard {
    /// @notice Threshold for executing a proposal
    uint8 APPROVE_THRESHOLD = 3;
    /// @notice Threshold for removing a proposal
    uint8 DISAPPROVE_THRESHOLD = 3;
    /// @notice Tokens configured on the contract
    mapping(address => ConfiguredToken) public configuredTokens;
    /// @notice Index of token contracts for easy enumerating
    address[] public configuredTokenContracts;
    /// @notice Player's currently locked tokens, can be multiple. Indexed by player then token contract
    mapping(address => mapping(address => LockedToken)) public lockedTokens;
    /// @notice Lock settings for each player
    mapping(address => PlayerSettings) playerSettings;
    /// @notice Current lockdrop start and end
    Lockdrop public lockdrop;
    /// @notice Current USD update proposal
    USDUpdateProposal usdUpdateProposal;
    /// @notice Used to make sure each approval is unique to a particular proposal
    uint32 private _usdProposalId;

    /// @notice Reference to the AccountManager contract
    IAccountManager public accountManager;

    /// @notice Reference to the SnuggeryManager.sol contract
    ISnuggeryManager public snuggeryManager;

    /// @notice Reference to the MigrationManager contract
    IMigrationManager public migrationManager;

    /// @notice Reference to the NFTOverlord contract to notify of unrevealed NFTs
    INFTOverlord public nftOverlord;

    /// @notice Token supplied must be configured but can be inactive
    modifier onlyConfiguredToken(address _tokenContract) {
        if (configuredTokens[_tokenContract].nftCost == 0)
            revert TokenNotConfiguredError();
        _;
    }

    /// @notice Token supplied must be configured and active
    modifier onlyActiveToken(address _tokenContract) {
        if (!configuredTokens[_tokenContract].active)
            revert TokenNotConfiguredError();
        _;
    }

    constructor(address _configStorage) {
        __BaseConfigStorage_setConfigStorage(_configStorage);
        _reconfigure();
    }

    function _reconfigure() internal {
        accountManager = IAccountManager(
            configStorage.getAddress(StorageKey.AccountManager)
        );

        migrationManager = IMigrationManager(
            configStorage.getAddress(StorageKey.MigrationManager)
        );

        snuggeryManager = ISnuggeryManager(
            configStorage.getAddress(StorageKey.SnuggeryManager)
        );

        nftOverlord = INFTOverlord(
            configStorage.getAddress(StorageKey.NFTOverlord)
        );

        super.__BaseBlastManager_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    fallback() external payable {
        revert LockManagerInvalidCallError();
    }

    receive() external payable {
        revert LockManagerRefuseETHError();
    }

    /// @inheritdoc ILockManager
    function configureLockdrop(
        Lockdrop calldata _lockdropData
    ) external onlyAdmin {
        if (_lockdropData.end < block.timestamp)
            revert LockdropEndedError(
                _lockdropData.end,
                uint32(block.timestamp)
            ); // , "LockManager: End date is in the past");
        if (_lockdropData.start >= _lockdropData.end)
            revert LockdropInvalidError();

        lockdrop = _lockdropData;

        emit LockDropConfigured(_lockdropData);
    }

    /// @inheritdoc ILockManager
    function configureToken(
        address _tokenContract,
        ConfiguredToken memory _tokenData
    ) external onlyAdmin {
        if (_tokenData.nftCost == 0) revert NFTCostInvalidError();
        if (configuredTokens[_tokenContract].nftCost == 0) {
            // new token
            configuredTokenContracts.push(_tokenContract);
        }
        configuredTokens[_tokenContract] = _tokenData;

        emit TokenConfigured(_tokenContract, _tokenData);
    }

    function setUSDThresholds(
        uint8 _approve,
        uint8 _disapprove
    ) external onlyAdmin {
        if (usdUpdateProposal.proposer != address(0))
            revert ProposalInProgressError();
        APPROVE_THRESHOLD = _approve;
        DISAPPROVE_THRESHOLD = _disapprove;

        emit USDThresholdUpdated(_approve, _disapprove);
    }

    /// @inheritdoc ILockManager
    function proposeUSDPrice(
        uint256 _price,
        address[] calldata _contracts
    )
        external
        onlyOneOfRoles(
            [
                Role.PriceFeed_1,
                Role.PriceFeed_2,
                Role.PriceFeed_3,
                Role.PriceFeed_4,
                Role.PriceFeed_5
            ]
        )
    {
        if (usdUpdateProposal.proposer != address(0))
            revert ProposalInProgressError();
        if (_contracts.length == 0) revert ProposalInvalidContractsError();

        delete usdUpdateProposal;

        // Approvals will use this because when the struct is deleted the approvals remain
        ++_usdProposalId;

        usdUpdateProposal.proposedDate = uint32(block.timestamp);
        usdUpdateProposal.proposer = msg.sender;
        usdUpdateProposal.proposedPrice = _price;
        usdUpdateProposal.contracts = _contracts;
        usdUpdateProposal.approvals[msg.sender] = _usdProposalId;
        usdUpdateProposal.approvalsCount++;

        emit ProposedUSDPrice(msg.sender, _price);
    }

    /// @inheritdoc ILockManager
    function approveUSDPrice(
        uint256 _price
    )
        external
        onlyOneOfRoles(
            [
                Role.PriceFeed_1,
                Role.PriceFeed_2,
                Role.PriceFeed_3,
                Role.PriceFeed_4,
                Role.PriceFeed_5
            ]
        )
    {
        if (usdUpdateProposal.proposer == address(0)) revert NoProposalError();
        if (usdUpdateProposal.proposer == msg.sender)
            revert ProposerCannotApproveError();
        if (usdUpdateProposal.approvals[msg.sender] == _usdProposalId)
            revert ProposalAlreadyApprovedError();
        if (usdUpdateProposal.disapprovals[msg.sender] == _usdProposalId)
            revert ProposalAlreadyDisapprovedError();
        if (usdUpdateProposal.proposedPrice != _price)
            revert ProposalPriceNotMatchedError();

        usdUpdateProposal.approvals[msg.sender] = _usdProposalId;
        usdUpdateProposal.approvalsCount++;

        if (usdUpdateProposal.approvalsCount >= APPROVE_THRESHOLD) {
            _execUSDPriceUpdate();
        }

        emit ApprovedUSDPrice(msg.sender);
    }

    /// @inheritdoc ILockManager
    function disapproveUSDPrice(
        uint256 _price
    )
        external
        onlyOneOfRoles(
            [
                Role.PriceFeed_1,
                Role.PriceFeed_2,
                Role.PriceFeed_3,
                Role.PriceFeed_4,
                Role.PriceFeed_5
            ]
        )
    {
        if (usdUpdateProposal.proposer == address(0)) revert NoProposalError();
        if (usdUpdateProposal.approvals[msg.sender] == _usdProposalId)
            revert ProposalAlreadyApprovedError();
        if (usdUpdateProposal.disapprovals[msg.sender] == _usdProposalId)
            revert ProposalAlreadyDisapprovedError();
        if (usdUpdateProposal.proposedPrice != _price)
            revert ProposalPriceNotMatchedError();

        usdUpdateProposal.disapprovalsCount++;
        usdUpdateProposal.disapprovals[msg.sender] = _usdProposalId;

        emit DisapprovedUSDPrice(msg.sender);

        if (usdUpdateProposal.disapprovalsCount >= DISAPPROVE_THRESHOLD) {
            delete usdUpdateProposal;

            emit RemovedUSDProposal();
        }
    }

    /// @inheritdoc ILockManager
    function setLockDuration(uint256 _duration) external notPaused {
        if (_duration > configStorage.getUint(StorageKey.MaxLockDuration))
            revert MaximumLockDurationError();

        accountManager.forceHarvest(msg.sender);
        playerSettings[msg.sender].lockDuration = uint32(_duration);
        // update any existing lock
        uint256 configuredTokensLength = configuredTokenContracts.length;
        for (uint256 i; i < configuredTokensLength; i++) {
            address tokenContract = configuredTokenContracts[i];
            if (lockedTokens[msg.sender][tokenContract].quantity > 0) {
                // check they are not setting lock time before current unlocktime
                uint32 lastLockTime = lockedTokens[msg.sender][tokenContract]
                    .lastLockTime;
                if (
                    lastLockTime + uint32(_duration) <
                    lockedTokens[msg.sender][tokenContract].unlockTime
                ) {
                    revert LockDurationReducedError();
                }

                lockedTokens[msg.sender][tokenContract].unlockTime =
                    lastLockTime +
                    uint32(_duration);
            }
        }

        emit LockDuration(msg.sender, _duration);
    }

    /// @inheritdoc ILockManager
    function lockOnBehalf(
        address _tokenContract,
        uint256 _quantity,
        address _onBehalfOf
    )
        external
        payable
        notPaused
        onlyActiveToken(_tokenContract)
        onlyConfiguredToken(_tokenContract)
        onlyConfiguredContract(StorageKey.MigrationManager)
        nonReentrant
    {
        address tokenOwner = msg.sender;
        address lockRecipient = _onBehalfOf;
        _lock(_tokenContract, _quantity, tokenOwner, lockRecipient);
    }

    /// @inheritdoc ILockManager
    function lock(
        address _tokenContract,
        uint256 _quantity
    )
        external
        payable
        notPaused
        onlyActiveToken(_tokenContract)
        onlyConfiguredToken(_tokenContract)
        nonReentrant
    {
        _lock(_tokenContract, _quantity, msg.sender, msg.sender);
    }

    function _lock(
        address _tokenContract,
        uint256 _quantity,
        address _tokenOwner,
        address _lockRecipient
    ) private {
        (
            address _mainAccount,
            MunchablesCommonLib.Player memory _player
        ) = accountManager.getPlayer(_lockRecipient);
        if (_mainAccount != _lockRecipient) revert SubAccountCannotLockError();
        if (_player.registrationDate == 0) revert AccountNotRegisteredError();
        // check approvals and value of tx matches
        if (_tokenContract == address(0)) {
            if (msg.value != _quantity) revert ETHValueIncorrectError();
        } else {
            if (msg.value != 0) revert InvalidMessageValueError();
            IERC20 token = IERC20(_tokenContract);
            uint256 allowance = token.allowance(_tokenOwner, address(this));
            if (allowance < _quantity) revert InsufficientAllowanceError();
        }

        LockedToken storage lockedToken = lockedTokens[_lockRecipient][
            _tokenContract
        ];
        ConfiguredToken storage configuredToken = configuredTokens[
            _tokenContract
        ];

        // they will receive schnibbles at the new rate since last harvest if not for force harvest
        accountManager.forceHarvest(_lockRecipient);

        // add remainder from any previous lock
        uint256 quantity = _quantity + lockedToken.remainder;
        uint256 remainder;
        uint256 numberNFTs;
        uint32 _lockDuration = playerSettings[_lockRecipient].lockDuration;

        if (_lockDuration == 0) {
            _lockDuration = lockdrop.minLockDuration;
        }
        if (
            lockdrop.start <= uint32(block.timestamp) &&
            lockdrop.end >= uint32(block.timestamp)
        ) {
            if (
                _lockDuration < lockdrop.minLockDuration ||
                _lockDuration >
                uint32(configStorage.getUint(StorageKey.MaxLockDuration))
            ) revert InvalidLockDurationError();
            if (msg.sender != address(migrationManager)) {
                // calculate number of nfts
                remainder = quantity % configuredToken.nftCost;
                numberNFTs = (quantity - remainder) / configuredToken.nftCost;

                if (numberNFTs > type(uint16).max) revert TooManyNFTsError();

                // Tell nftOverlord that the player has new unopened Munchables
                nftOverlord.addReveal(_lockRecipient, uint16(numberNFTs));

                lockedToken.remainder = remainder;
            }
        }

        // Transfer erc tokens
        if (_tokenContract != address(0)) {
            IERC20 token = IERC20(_tokenContract);
            SafeERC20.safeTransferFrom(
                token,
                _tokenOwner,
                address(this),
                _quantity
            );
        }

        lockedToken.quantity += _quantity;
        lockedToken.lastLockTime = uint32(block.timestamp);
        lockedToken.unlockTime =
            uint32(block.timestamp) +
            uint32(_lockDuration);

        // set their lock duration in playerSettings
        playerSettings[_lockRecipient].lockDuration = _lockDuration;

        emit Locked(
            _lockRecipient,
            _tokenOwner,
            _tokenContract,
            _quantity,
            remainder,
            numberNFTs,
            _lockDuration
        );
    }

    /// @inheritdoc ILockManager
    function unlock(
        address _tokenContract,
        uint256 _quantity
    ) external notPaused nonReentrant {
        LockedToken storage lockedToken = lockedTokens[msg.sender][
            _tokenContract
        ];
        if (lockedToken.quantity < _quantity)
            revert InsufficientLockAmountError();
        if (lockedToken.unlockTime > uint32(block.timestamp))
            revert TokenStillLockedError();

        // force harvest to make sure that they get the schnibbles that they are entitled to
        accountManager.forceHarvest(msg.sender);

        lockedToken.quantity -= _quantity;
        lockedToken.remainder = 0;

        // send token
        if (_tokenContract == address(0)) {
            (bool success, ) = payable(msg.sender).call{value: _quantity}("");
            if (!success) revert FailedTransferError();
        } else {
            IERC20 token = IERC20(_tokenContract);
            token.transfer(msg.sender, _quantity);
        }

        emit Unlocked(msg.sender, _tokenContract, _quantity);
    }

    /// @inheritdoc ILockManager
    function getLocked(
        address _player
    ) external view returns (LockedTokenWithMetadata[] memory _lockedTokens) {
        uint256 configuredTokensLength = configuredTokenContracts.length;
        LockedTokenWithMetadata[]
            memory tmpLockedTokens = new LockedTokenWithMetadata[](
                configuredTokensLength
            );
        for (uint256 i; i < configuredTokensLength; i++) {
            LockedToken memory tmpLockedToken;
            tmpLockedToken.unlockTime = lockedTokens[_player][
                configuredTokenContracts[i]
            ].unlockTime;
            tmpLockedToken.quantity = lockedTokens[_player][
                configuredTokenContracts[i]
            ].quantity;
            tmpLockedToken.lastLockTime = lockedTokens[_player][
                configuredTokenContracts[i]
            ].lastLockTime;
            tmpLockedToken.remainder = lockedTokens[_player][
                configuredTokenContracts[i]
            ].remainder;
            tmpLockedTokens[i] = LockedTokenWithMetadata(
                tmpLockedToken,
                configuredTokenContracts[i]
            );
        }
        _lockedTokens = tmpLockedTokens;
    }

    /// @inheritdoc ILockManager
    function getLockedWeightedValue(
        address _player
    ) external view returns (uint256 _lockedWeightedValue) {
        uint256 lockedWeighted = 0;
        uint256 configuredTokensLength = configuredTokenContracts.length;
        for (uint256 i; i < configuredTokensLength; i++) {
            if (
                lockedTokens[_player][configuredTokenContracts[i]].quantity >
                0 &&
                configuredTokens[configuredTokenContracts[i]].active
            ) {
                // We are assuming all tokens have a maximum of 18 decimals and that USD Price is denoted in 1e18
                uint256 deltaDecimal = 10 **
                    (18 -
                        configuredTokens[configuredTokenContracts[i]].decimals);
                lockedWeighted +=
                    (deltaDecimal *
                        lockedTokens[_player][configuredTokenContracts[i]]
                            .quantity *
                        configuredTokens[configuredTokenContracts[i]]
                            .usdPrice) /
                    1e18;
            }
        }

        _lockedWeightedValue = lockedWeighted;
    }

    /// @inheritdoc ILockManager
    function getConfiguredToken(
        address _tokenContract
    ) external view returns (ConfiguredToken memory _token) {
        _token = configuredTokens[_tokenContract];
    }

    function getPlayerSettings(
        address _player
    ) external view returns (PlayerSettings memory _settings) {
        _settings = playerSettings[_player];
    }

    /*******************************************************
     ** INTERNAL FUNCTIONS
     ********************************************************/

    function _execUSDPriceUpdate() internal {
        if (
            usdUpdateProposal.approvalsCount >= APPROVE_THRESHOLD &&
            usdUpdateProposal.disapprovalsCount < DISAPPROVE_THRESHOLD
        ) {
            uint256 updateTokensLength = usdUpdateProposal.contracts.length;
            for (uint256 i; i < updateTokensLength; i++) {
                address tokenContract = usdUpdateProposal.contracts[i];
                if (configuredTokens[tokenContract].nftCost != 0) {
                    configuredTokens[tokenContract].usdPrice = usdUpdateProposal
                        .proposedPrice;

                    emit USDPriceUpdated(
                        tokenContract,
                        usdUpdateProposal.proposedPrice
                    );
                }
            }

            delete usdUpdateProposal;
        }
    }
}
"},"src/managers/MigrationManager.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import "@openzeppelin/contracts/interfaces/IERC721.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/interfaces/IERC20.sol";
import "../interfaces/IMigrationManager.sol";
import "../interfaces/IMunchNFT.sol";
import "../interfaces/INFTAttributesManager.sol";
import "../interfaces/ILockManager.sol";
import "./BaseBlastManager.sol";
import "../interfaces/ISnuggeryManager.sol";
import "../interfaces/IClaimManager.sol";
import "../interfaces/INFTOverlord.sol";

contract MigrationManager is
    IMigrationManager,
    ReentrancyGuard,
    BaseBlastManager
{
    uint8 constant SKIP_AMOUNT = 5;
    uint256 public discountFactor;
    uint256 public purchasedUnlockPrice = 2 ether;
    bool public seal;

    IOldNFT _oldNFTContract;
    INFTAttributesManager _attributesManager;
    ILockManager _lockManager;
    ISnuggeryManager _snuggeryManager;
    IClaimManager _claimManager;
    INFTOverlord _nftOverlord;
    mapping(bytes32 => MigrationSnapshotData) _migrationSnapshots;
    mapping(address => bool) _userClaimedOnce;
    mapping(address => uint256[]) _userTokenIds;
    mapping(address => uint16) _unrevealed;
    mapping(address => UserLockedChoice) _userLockedAction;
    mapping(address => UserLockedChoice) _userPurchasedAction;
    mapping(address => MigrationTotals) _userLockedAmounts;
    address LOCAL_ADMIN;

    modifier onlyLocalAdmin() {
        if (msg.sender != LOCAL_ADMIN) revert InvalidRoleError();
        _;
    }

    constructor(address _configStorage) {
        __BaseConfigStorage_setConfigStorage(_configStorage);
        _reconfigure();
        LOCAL_ADMIN = msg.sender;
    }

    function _reconfigure() internal {
        // load config from the config storage contract and configure myself, USDB/WETH config is handled by base
        _lockManager = ILockManager(
            configStorage.getAddress(StorageKey.LockManager)
        );

        _oldNFTContract = IOldNFT(
            configStorage.getAddress(StorageKey.OldMunchNFT)
        );

        _attributesManager = INFTAttributesManager(
            configStorage.getAddress(StorageKey.NFTAttributesManager)
        );

        _claimManager = IClaimManager(
            configStorage.getAddress(StorageKey.ClaimManager)
        );

        _nftOverlord = INFTOverlord(
            configStorage.getAddress(StorageKey.NFTOverlord)
        );

        discountFactor = configStorage.getUint(
            StorageKey.MigrationDiscountFactor
        );

        super.__BaseBlastManager_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    function loadMigrationSnapshot(
        address[] calldata users,
        MigrationSnapshotData[] calldata data
    ) external override onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (users.length != data.length) revert InvalidDataLengthError();
        address _user;
        uint256 _tokenId;
        bytes32 key;
        for (uint256 i = 0; i < users.length; i++) {
            if (
                data[i].token != address(USDB) &&
                data[i].token != address(WETH) &&
                data[i].token != address(0)
            ) revert InvalidMigrationTokenError();
            if (data[i].tokenId == 0) revert InvalidMigrationTokenIdError();
            _user = users[i];
            _tokenId = data[i].tokenId;
            key = keccak256(abi.encodePacked(_user, _tokenId));
            if (_migrationSnapshots[key].tokenId != 0)
                revert DataAlreadyLoadedError();
            _migrationSnapshots[key] = data[i];

            if (data[i].lockAmount != 0) {
                _userLockedAmounts[_user].totalLockedAmount += data[i]
                    .lockAmount;
                _userLockedAmounts[_user].tokenLocked = data[i].token;
            } else {
                if (data[i].token != address(0))
                    revert InvalidMigrationTokenError();
                _userLockedAmounts[_user]
                    .totalPurchasedAmount += purchasedUnlockPrice;
            }
            _userTokenIds[_user].push(_tokenId);
        }
        emit MigrationSnapshotLoaded(users, data);
    }

    event TokenClaimed(bytes32[] _snapshot, bool[] claimed);

    function setTokenClaimed(
        bytes32[] calldata _snapshot,
        bool[] calldata claimed
    ) external onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (_snapshot.length != claimed.length) revert InvalidDataLengthError();
        for (uint256 i = 0; i < _snapshot.length; i++) {
            bytes32 key = _snapshot[i];
            if (_migrationSnapshots[key].tokenId == 0)
                revert NoMigrationExistsError();
            _migrationSnapshots[key].claimed = claimed[i];
        }
        emit TokenClaimed(_snapshot, claimed);
    }

    event UserClaimedOnce(address[] users, bool[] setter);

    function setUserClaimedOnce(
        address[] calldata users,
        bool[] calldata setter
    ) external onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (users.length != setter.length) revert InvalidDataLengthError();
        for (uint256 i = 0; i < users.length; i++) {
            _userClaimedOnce[users[i]] = setter[i];
        }
        emit UserClaimedOnce(users, setter);
    }

    event UserClaimedLockedAction(address[] users, UserLockedChoice[] setter);

    function setUserLockedAction(
        address[] calldata users,
        UserLockedChoice[] calldata setter
    ) external onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (users.length != setter.length) revert InvalidDataLengthError();
        for (uint256 i = 0; i < users.length; i++) {
            _userLockedAction[users[i]] = setter[i];
        }
        emit UserClaimedLockedAction(users, setter);
    }

    event UserPurchasedLockedAction(address[] users, UserLockedChoice[] setter);

    function setUserPurchasedAction(
        address[] calldata users,
        UserLockedChoice[] calldata setter
    ) external onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (users.length != setter.length) revert InvalidDataLengthError();
        for (uint256 i = 0; i < users.length; i++) {
            _userPurchasedAction[users[i]] = setter[i];
        }
        emit UserPurchasedLockedAction(users, setter);
    }

    function sealData() external override onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        seal = true;
        emit MigrationDataSealed();
    }

    function loadUnrevealedSnapshot(
        address[] calldata users,
        uint16[] calldata unrevealed
    ) external onlyLocalAdmin {
        if (seal) revert MigrationDataSealedError();
        if (users.length != unrevealed.length) revert InvalidDataLengthError();
        for (uint256 i = 0; i < users.length; i++) {
            _unrevealed[users[i]] = unrevealed[i];
        }

        emit UnrevealedSnapshotLoaded(users, unrevealed);
    }

    function burnUnrevealedForPoints() external {
        if (!seal) revert MigrationDataNotSealedError();
        if (_unrevealed[msg.sender] == 0) revert NoUnrevealedError();

        uint256 amountToSwap = uint256(_unrevealed[msg.sender]);

        _claimManager.burnUnrevealedForPoints(msg.sender, amountToSwap);

        delete _unrevealed[msg.sender];

        emit UnrevealedSwapSucceeded(msg.sender, amountToSwap);
    }

    function burnNFTs(address _user, uint32 _skip) external override {
        if (!seal) revert MigrationDataNotSealedError();
        if (
            _user != msg.sender &&
            _userLockedAction[_user] == UserLockedChoice.NONE
        ) revert SelfNeedsToChooseError();
        if (_userLockedAction[_user] == UserLockedChoice.LOCKED_FULL_MIGRATION)
            revert DifferentLockActionError();

        uint256[] memory tokenIds = _userTokenIds[_user];
        if (tokenIds.length == 0) revert NoNFTsToBurnError();
        uint8[] memory tokenIdsByRarity = new uint8[](7);
        uint256 tokenId;
        MigrationSnapshotData storage snapshot;
        uint256 maxLength = _skip + SKIP_AMOUNT > tokenIds.length
            ? tokenIds.length
            : _skip + SKIP_AMOUNT;
        uint256[] memory burnedTokenIds = new uint256[](maxLength - _skip);
        for (uint256 i = _skip; i < maxLength; i++) {
            tokenId = tokenIds[i];
            snapshot = _migrationSnapshots[
                keccak256(abi.encodePacked(_user, tokenId))
            ];
            if (snapshot.lockAmount == 0 || snapshot.claimed) continue;
            if (snapshot.tokenId == 0) revert NoMigrationExistsError();
            snapshot.claimed = true;
            tokenIdsByRarity[uint8(snapshot.immutableAttributes.rarity)]++;
            _oldNFTContract.burn(tokenId);
            burnedTokenIds[i - _skip] = tokenId;
        }

        _claimManager.burnNFTsForPoints(_user, tokenIdsByRarity);
        _userLockedAction[_user] = UserLockedChoice.LOCKED_BURN;
        emit BurnSucceeded(_user, burnedTokenIds);
    }

    function burnRemainingPurchasedNFTs(
        address _user,
        uint32 _skip
    ) external override {
        if (!seal) revert MigrationDataNotSealedError();
        if (
            _user != msg.sender &&
            _userPurchasedAction[_user] == UserLockedChoice.NONE
        ) revert SelfNeedsToChooseError();
        _userPurchasedAction[_user] = UserLockedChoice.LOCKED_BURN;
        uint256[] memory tokenIds = _userTokenIds[_user];
        if (tokenIds.length == 0) revert NoNFTsToBurnError();
        uint8[] memory tokenIdsByRarity = new uint8[](7);
        uint256 maxLength = _skip + SKIP_AMOUNT > tokenIds.length
            ? tokenIds.length
            : _skip + SKIP_AMOUNT;
        uint256[] memory burnedTokens = new uint256[](maxLength - _skip);

        uint256 tokenId;
        bytes32 key;
        MigrationSnapshotData memory snapshot;
        for (uint256 i = _skip; i < maxLength; i++) {
            tokenId = tokenIds[i];
            key = keccak256(abi.encodePacked(_user, tokenId));
            snapshot = _migrationSnapshots[key];
            if (snapshot.lockAmount != 0 || snapshot.claimed) continue;
            if (snapshot.tokenId == 0) revert NoMigrationExistsError();
            _migrationSnapshots[key].claimed = true;
            tokenIdsByRarity[uint8(snapshot.immutableAttributes.rarity)]++;
            _oldNFTContract.burn(tokenId);
            burnedTokens[i - _skip] = tokenId;
        }

        _claimManager.burnNFTsForPoints(_user, tokenIdsByRarity);
        emit BurnPurchasedSucceeded(_user, burnedTokens);
    }

    function lockFundsForAllMigration() external payable override nonReentrant {
        if (!seal) revert MigrationDataNotSealedError();
        if (_userLockedAction[msg.sender] != UserLockedChoice.NONE)
            revert DifferentLockActionError();
        _userClaimedOnce[msg.sender] = true;
        (uint256 totalLockAmount, ) = getUserMigrateQuantityAll(msg.sender);
        if (totalLockAmount == 0) revert NoMigrationExistsError();
        if (_userTokenIds[msg.sender].length == 0) revert NoNFTsToBurnError();
        address tokenContract = _userLockedAmounts[msg.sender].tokenLocked;
        if (tokenContract == address(0)) {
            if (msg.value != totalLockAmount)
                revert InvalidMigrationAmountError();
        } else {
            if (msg.value != 0) revert InvalidMigrationAmountError();
            IERC20(tokenContract).transferFrom(
                msg.sender,
                address(this),
                totalLockAmount
            );
        }

        _userLockedAction[msg.sender] = UserLockedChoice.LOCKED_FULL_MIGRATION;
        emit LockedForMigration(msg.sender, totalLockAmount, tokenContract);
    }

    function migrateAllNFTs(address _user, uint32 _skip) external override {
        if (_userLockedAction[_user] != UserLockedChoice.LOCKED_FULL_MIGRATION)
            revert DifferentLockActionError();
        uint256 maxSize = _userTokenIds[_user].length;
        if (_skip >= maxSize) revert InvalidSkipAmountError();
        uint256 maxLengthArray = _skip + SKIP_AMOUNT > maxSize
            ? maxSize
            : _skip + SKIP_AMOUNT;
        uint256[] memory tokenIds = new uint256[](maxLengthArray - _skip);
        MigrationSnapshotData memory snapshot;
        for (uint256 i = _skip; i < maxLengthArray; i++) {
            snapshot = _migrationSnapshots[
                keccak256(abi.encodePacked(_user, _userTokenIds[_user][i]))
            ];
            if (snapshot.lockAmount != 0) {
                tokenIds[i - _skip] = _userTokenIds[_user][i];
            }
        }
        _migrateNFTs(_user, _userLockedAmounts[_user].tokenLocked, tokenIds);
    }

    function migratePurchasedNFTs(
        uint256[] memory tokenIds
    ) external payable override nonReentrant {
        if (_userPurchasedAction[msg.sender] != UserLockedChoice.NONE)
            revert DifferentLockActionError();
        MigrationSnapshotData memory snapshot;
        uint256 quantity;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            if (tokenIds[i] == 0) continue;
            snapshot = _migrationSnapshots[
                keccak256(abi.encodePacked(msg.sender, tokenIds[i]))
            ];
            if (snapshot.lockAmount != 0) revert NotBoughtNFTError();
            if (snapshot.token != address(0))
                revert NFTPurchasedContractError();
            if (snapshot.claimed) continue;
            quantity += purchasedUnlockPrice;
        }
        _migrateNFTs(msg.sender, address(0), tokenIds);
        if (msg.value != (quantity * discountFactor) / 10e12)
            revert InvalidMigrationAmountError();
    }

    function rescue(
        address _tokenContract,
        uint256 _quantity,
        address _returnAddress
    ) external onlyAdmin {
        if (_tokenContract == address(0)) {
            bool res = payable(_returnAddress).send(_quantity);
            if (!res) revert RescueTransferError();
        } else {
            IERC20(_tokenContract).transferFrom(
                address(this),
                _returnAddress,
                _quantity
            );
        }
    }

    function _migrateNFTs(
        address _user,
        address _tokenLocked,
        uint256[] memory tokenIds
    ) internal {
        if (!seal) revert MigrationDataNotSealedError();

        uint256 totalLockAmount;
        uint256 tokenId;
        bytes32 key;
        MigrationSnapshotData storage snapshot;
        uint256[] memory newTokenIds = new uint256[](tokenIds.length);
        uint256[] memory migratedTokenIds = new uint256[](tokenIds.length);
        uint8 i;
        for (; i < tokenIds.length; i++) {
            tokenId = tokenIds[i];
            if (tokenId == 0) continue;
            key = keccak256(abi.encodePacked(_user, tokenId));
            // We re-use the snapshot variable here to save on gas
            snapshot = _migrationSnapshots[key];
            if (snapshot.tokenId == 0) revert NoMigrationExistsError();
            if (snapshot.claimed) continue;

            snapshot.claimed = true;

            uint256 lockAmount = snapshot.lockAmount;
            if (lockAmount == 0) {
                totalLockAmount += purchasedUnlockPrice;
            } else {
                totalLockAmount += lockAmount;
            }

            snapshot.immutableAttributes.hatchedDate = uint32(block.timestamp);
            newTokenIds[i] = _nftOverlord.mintForMigration(
                _user,
                snapshot.attributes,
                snapshot.immutableAttributes,
                snapshot.gameAttributes
            );
            migratedTokenIds[i] = snapshot.tokenId;

            _oldNFTContract.burn(tokenId);
        }

        uint256 quantity = (totalLockAmount * discountFactor) / 10e12;
        if (quantity > 0) {
            if (_tokenLocked == address(0)) {
                _lockManager.lockOnBehalf{value: quantity}(
                    _tokenLocked,
                    quantity,
                    _user
                );
            } else if (_tokenLocked == address(WETH)) {
                WETH.approve(address(_lockManager), quantity);
                _lockManager.lockOnBehalf(_tokenLocked, quantity, _user);
            } else if (_tokenLocked == address(USDB)) {
                USDB.approve(address(_lockManager), quantity);
                _lockManager.lockOnBehalf(_tokenLocked, quantity, _user);
            }
        }
        emit MigrationSucceeded(_user, migratedTokenIds, newTokenIds);
    }

    function getUserMigrateQuantityAll(
        address _user
    )
        public
        view
        returns (uint256 totalLockAmount, uint256 totalPurchaseAmount)
    {
        totalLockAmount =
            (_userLockedAmounts[_user].totalLockedAmount * discountFactor) /
            10e12;
        totalPurchaseAmount =
            (_userLockedAmounts[_user].totalPurchasedAmount * discountFactor) /
            10e12;
    }

    function getUserMigrationData(
        address _user,
        uint256 _tokenId
    ) external view returns (MigrationSnapshotData memory) {
        bytes32 key = keccak256(abi.encodePacked(_user, _tokenId));
        return _migrationSnapshots[key];
    }

    function getUserMigrationCompletedData(
        address _user
    ) external view override returns (bool, MigrationTotals memory) {
        return (_userClaimedOnce[_user], _userLockedAmounts[_user]);
    }

    function getUserUnrevealedData(
        address _user
    ) external view returns (uint16) {
        return _unrevealed[_user];
    }

    function getUserNFTsLength(address _user) external view returns (uint256) {
        return _userTokenIds[_user].length;
    }
}
"},"src/managers/MunchadexManager.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import "openzeppelin-contracts/contracts/token/ERC721/IERC721.sol";
import "./BaseBlastManager.sol";
import "../interfaces/IMunchNFT.sol";
import "../interfaces/IMunchadexManager.sol";
import "../interfaces/INFTAttributesManager.sol";
import "../interfaces/IAccountManager.sol";

contract MunchadexManager is BaseBlastManager, IMunchadexManager {
    mapping(address => MunchablesCommonLib.Munchadex) munchadex;

    INFTAttributesManager nftAttributesManager;
    address snuggeryManagerAddress;
    IAccountManager accountManager;

    constructor(address _configStorage) {
        __BaseConfigStorage_setConfigStorage(_configStorage);
        _reconfigure();
    }

    function _reconfigure() internal {
        nftAttributesManager = INFTAttributesManager(
            configStorage.getAddress(StorageKey.NFTAttributesManager)
        );
        snuggeryManagerAddress = configStorage.getAddress(
            StorageKey.SnuggeryManager
        );
        accountManager = IAccountManager(
            configStorage.getAddress(StorageKey.AccountManager)
        );

        super.__BaseBlastManager_reconfigure();
    }

    function configUpdated() external override onlyConfigStorage {
        _reconfigure();
    }

    function updateMunchadex(
        address _from,
        address _to,
        uint256 _tokenId
    ) external override onlyConfiguredContract(StorageKey.MunchNFT) {
        if (_from == snuggeryManagerAddress || _to == snuggeryManagerAddress)
            return;

        MunchablesCommonLib.NFTImmutableAttributes
            memory immutableAttributes = nftAttributesManager
                .getImmutableAttributes(_tokenId);
        if (_from != address(0)) {
            MunchablesCommonLib.Munchadex storage fromMunchadex = munchadex[
                _from
            ];
            if (
                --fromMunchadex.unique[
                    keccak256(abi.encodePacked(immutableAttributes.species))
                ] == 0
            ) {
                fromMunchadex.numInRealm[immutableAttributes.realm]--;
                fromMunchadex.numInRarity[immutableAttributes.rarity]--;
                fromMunchadex.numUnique--;
                accountManager.forceHarvest(_from);
            }

            emit MunchadexUpdated(
                _from,
                _tokenId,
                immutableAttributes.realm,
                immutableAttributes.rarity,
                fromMunchadex.numInRealm[immutableAttributes.realm],
                fromMunchadex.numInRarity[immutableAttributes.rarity],
                fromMunchadex.numUnique
            );
        }
        if (_to != address(0)) {
            MunchablesCommonLib.Munchadex storage toMunchadex = munchadex[_to];
            if (
                toMunchadex.unique[
                    keccak256(abi.encodePacked(immutableAttributes.species))
                ]++ == 0
            ) {
                toMunchadex.numInRealm[immutableAttributes.realm]++;
                toMunchadex.numInRarity[immutableAttributes.rarity]++;
                toMunchadex.numUnique++;
                accountManager.forceHarvest(_to);
            }

            emit MunchadexUpdated(
                _to,
                _tokenId,
                immutableAttributes.realm,
                immutableAttributes.rarity,
                toMunchadex.numInRealm[immutableAttributes.realm],
                toMunchadex.numInRarity[immutableAttributes.rarity],
                toMunchadex.numUnique
            );
        }
    }

    function getMunchadexInfo(
        address _player
    )
        external
        view
        override
        returns (
            uint256[] memory numMunchablesPerRealm,
            uint256[] memory numMunchablesPerRarity,
            uint256 numUnique
        )
    {
        MunchablesCommonLib.Munchadex storage playerMunchadex = munchadex[
            _player
        ];
        numMunchablesPerRealm = new uint256[](
            uint256(MunchablesCommonLib.Realm.Invalid)
        );
        numMunchablesPerRarity = new uint256[](
            uint256(MunchablesCommonLib.Rarity.Invalid)
        );

        for (uint256 i; i < uint256(MunchablesCommonLib.Realm.Invalid); i++) {
            numMunchablesPerRealm[i] = playerMunchadex.numInRealm[
                MunchablesCommonLib.Realm(i)
            ];
        }

        for (uint256 i; i < uint256(MunchablesCommonLib.Rarity.Invalid); i++) {
            numMunchablesPerRarity[i] = playerMunchadex.numInRarity[
                MunchablesCommonLib.Rarity(i)
            ];
        }

        numUnique = playerMunchadex.numUnique;
    }
}
