import "../libraries/MunchablesCommonLib.sol";
import "openzeppelin-contracts-upgradeable/contracts/utils/PausableUpgradeable.sol";

contract OldMunchNFT is
    Initializable,
    ERC721Upgradeable,
    ERC721EnumerableUpgradeable,
